import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom fused scale+add kernel
fused_scale_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_scale_add_kernel(const float* input, float* output, float scaling_factor, int size) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        const float val = input[idx];
        output[idx] = val * scaling_factor + val;
    }
}

torch::Tensor fused_scale_add_cuda(torch::Tensor input, float scaling_factor) {
    auto output = torch::empty_like(input);
    const int size = input.numel();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    fused_scale_add_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        scaling_factor,
        size
    );

    return output;
}
"""

fused_scale_add_cpp_source = "torch::Tensor fused_scale_add_cuda(torch::Tensor input, float scaling_factor);"

fused_scale_add = load_inline(
    name="fused_scale_add",
    cpp_sources=fused_scale_add_cpp_source,
    cuda_sources=fused_scale_add_source,
    functions=["fused_scale_add_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, scaling_factor):
        super(ModelNew, self).__init__()
        self.matmul = nn.Linear(in_features, out_features)
        self.scaling_factor = scaling_factor

    def forward(self, x):
        x = self.matmul(x)
        x = fused_scale_add.fused_scale_add_cuda(x, self.scaling_factor)
        return x
